INSERT INTO temp_import_pages VALUES ('{"pageId": "e0500000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 50, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "50", "printedPageNumber": 50, "pdfPageNumber": 433, "sequenceIndex": 40, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0500100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "IMPORTANCE OF JAMAAT", "sourceIdentifier": null, "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}, {"id": "b0500200-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "CHAPTER I", "sourceIdentifier": null, "title": null, "sequenceIndex": 1, "startPageId": null, "endPageId": null}, {"id": "b0500300-0000-4000-8000-000000000001", "parentId": null, "nodeType": "section", "sourceLabel": "REWARDS OF JAMAAT", "sourceIdentifier": null, "title": null, "sequenceIndex": 2, "startPageId": null, "endPageId": null}, {"id": "b0500400-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith I", "sourceIdentifier": "I", "title": null, "sequenceIndex": 3, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0500000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "PART II", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}, {"id": "f0500100-0000-4000-8000-000000000001", "structuralNodeId": "b0500100-0000-4000-8000-000000000001", "sequenceIndex": 1, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "IMPORTANCE OF JAMAAT", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}, {"id": "f0500200-0000-4000-8000-000000000001", "structuralNodeId": "b0500100-0000-4000-8000-000000000001", "sequenceIndex": 2, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "As has already been said in the foreword, there are many who say their salaat regularly but are not very particular about Jamaat. The Prophet (Sallallaho alaihe wasallam) is as emphatic in enjoining Jamaat as he is particular about salaat. This part also consists of two chapters. The first deals with the rewards of Jamaat and the second with the consequences of its neglect.", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}, {"id": "f0500300-0000-4000-8000-000000000001", "structuralNodeId": "b0500200-0000-4000-8000-000000000001", "sequenceIndex": 3, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "CHAPTER I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}, {"id": "f0500400-0000-4000-8000-000000000001", "structuralNodeId": "b0500300-0000-4000-8000-000000000001", "sequenceIndex": 4, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "REWARDS OF JAMAAT", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}, {"id": "f0500500-0000-4000-8000-000000000001", "structuralNodeId": "b0500400-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith I", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}, {"id": "f0500600-0000-4000-8000-000000000001", "structuralNodeId": "b0500400-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن ابن عمر رضي الله عنه أن رسول الله ﷺ قال صلاة الجماعة أفضل من صلاة الفذ بسبع وعشرين درجة رواه مالك والبخاري ومسلم والترمذي كذا في الترغيب", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}, {"id": "f0500700-0000-4000-8000-000000000001", "structuralNodeId": "b0500400-0000-4000-8000-000000000001", "sequenceIndex": 7, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abdullah bin Umar (Radhiyallaho anha) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying: \"A salaat with Jamaat is twenty-seven times superior to salaat performed individually.\"\n\nWhen we offer our salaat for getting reward from Allah, then why should it not be done in the musjid, where the reward earned is twenty-seven times more. Nobody will be so unwise as to forego a profit twenty-seven times greater with simply a little extra labour. But we are so indifferent about the profits promised for our religious practices! This can be due to nothing but our disregard for deen and the rewards of it. It is a pity that we apply ourselves so hard to acquiring the trifling gains in this material world; but are so unmindful of the gains in the Hereafter, which yield twenty-seven times more with a little extra effort. We often argue that for going to the musjid for Jamaat we have to close the shop and will thus lose business. These pretexts and others of the kind cannot stand in the way of those who have perfect faith in the Greatness of Allah, and", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 50"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0510000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 51, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "51", "printedPageNumber": 51, "pdfPageNumber": 434, "sequenceIndex": 41, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [{"id": "b0510100-0000-4000-8000-000000000001", "parentId": null, "nodeType": "hadith", "sourceLabel": "Hadith II", "sourceIdentifier": "II", "title": null, "sequenceIndex": 0, "startPageId": null, "endPageId": null}], "blocks": [{"id": "f0510000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Part II (a)—Rewards of Jamaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "in His word; and who realize the value of the blessings and reward in the Hereafter. It is in respect of such people that Allah says:", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "رِجَالٌ لَا تُلْهِيهِمْ تِجَارَةٌ وَلَا بَيْعٌ عَنْ ذِكْرِ اللَّهِ وَإِقَامِ الصَّلَاةِ", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510300-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 3, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "\"Men, whom neither merchandise nor sale beguileth them from remembrance of Allah and constancy in ''salaat.''\" (XXIV: 37).", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510400-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 4, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "It is said of Saalim Haddaad (Rahmatullah alaih) (a trader and a great Soofi) that on hearing Azaan he would turn pale and grow restless. He would stand up immediately, leaving his shop open and recite these couplets:-\n\n1. \"When Thy summoner stands up to summon,\nquickly I stand up.\nTo respond to (the summons of) The Mighty Lord\nWho hath no peer.\"\n\n2. \"I reply to the summons with complete submission and cheer,\n''Here am I, O Bountiful One.''\"\n\n3. \"My face grows pale with awe and fear, and occupation in Thee distracts me from all other occupations.\"\n\n4. \"I swear by Thee, naught is dear to me save Thy remembrance.\nNothing is more ravishing for me than Thy sweet name.\"\n\n5. \"O, will there be a time for us to be together?\nA lover is happy only when he is with his love.\"\n\n6. \"He whose eyes have seen the light of Thy Beauty\nCan never be solaced. He must die yearning for Thee.\"\n\nIt is said in a hadith: \"People frequenting the musjid are its pegs (dwellers). Angels are their companions and visit them when they are sick and help them when they are at their jobs.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510500-0000-4000-8000-000000000001", "structuralNodeId": "b0510100-0000-4000-8000-000000000001", "sequenceIndex": 5, "blockType": "heading", "languageCode": "en", "direction": "ltr", "textContent": "Hadith II", "rawOcrText": null, "ttsEligible": false, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}, {"id": "f0510600-0000-4000-8000-000000000001", "structuralNodeId": "b0510100-0000-4000-8000-000000000001", "sequenceIndex": 6, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "عن أبي هريرة رضي الله عنه قال قال رسول الله ﷺ صلاة الرجل في جماعة تضعف على صلاته في بيته وفي سوقه خمساً وعشرين ضعفاً وذلك أنه إذا", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 51"}]}'::jsonb);
INSERT INTO temp_import_pages VALUES ('{"pageId": "e0520000-0000-4000-8000-000000000001", "bookPartId": "59d7f112-fb58-4726-9c35-11485c6155e7", "pageNumber": 52, "sourceShowsPrintedPageLabel": true, "printedPageLabel": "52", "printedPageNumber": 52, "pdfPageNumber": 435, "sequenceIndex": 42, "verificationStatus": "in_review", "scanLanguages": ["en", "ar"], "reviewEvidence": {"englishTranscriptionComplete": true, "arabicTranscriptionComplete": true, "blockOrderChecked": true, "identifiersChecked": true, "scanCompared": true}, "structuralNodes": [], "blocks": [{"id": "f0520000-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 0, "blockType": "english", "languageCode": "en", "direction": "ltr", "textContent": "Virtues of Salaat", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 52"}, {"id": "f0520100-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 1, "blockType": "arabic", "languageCode": "ar", "direction": "rtl", "textContent": "توضأ فأحسن الوضوء ثم خرج إلى المسجد لا يخرجه إلا الصلاة لم يخط خطوة إلا رفعت له بها درجة وحط عنه بها خطيئة فإذا صلى لم تزل الملائكة تصلي عليه ما دام في مصلاه اللهم صل عليه اللهم ارحمه ولا يزال في صلاة ما انتظر الصلاة", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 52"}, {"id": "f0520200-0000-4000-8000-000000000001", "structuralNodeId": null, "sequenceIndex": 2, "blockType": "translation", "languageCode": "en", "direction": "ltr", "textContent": "Hadhrat Abu Hurairah (Radhiyallaho anho) narrates that he heard the Prophet (Sallallaho alaihe wasallam) saying, \"Salaat with Jamaat is twenty-five times superior to salaat which is said in a house or in a shop. It is so because when a person performs wudhu in right earnest and walks on to the musjid, with the sole intention of performing salaat, each step he takes, adds one blessing to his account and wipes out one sin therefrom. Again, if he keeps sitting in the musjid (with wudhu of course) after the salaat is over, the angels keep on seeking Allah''s blessing and forgiveness for him. And as long as he keeps sitting in the musjid waiting for salaat; he goes on earning rewards as if he is busy in salaat.\"\n\nIn Hadith No. I, the superiority of salaat with Jamaat over that offered individually is described as being twenty-seven times more, while this hadith mentions only twenty-five times. Various theologians have discussed at length this seeming inconsistency. The following are some of the explanations:\n\n1. \"This variation from twenty-five to twenty-seven is due to variation of ikhlaas (sincerity) in different individuals.\"\n\n2. \"In Sirri (quiet) salaat (i.e., Zuhr and Asr), it is twenty-five times, while in Jahri (loud) salaat (i.e., Fajr, Maghrib and Ishaa), it is twenty-seven times.\"\n\n3. \"In Fajr and Ishaa, when it is somewhat inconvenient to go out due to cold and darkness, it is twenty-seven times, but in other salaats it is twenty-five times.\"\n\n4. \"In the beginning it was twenty-five times, but subsequently Allah (by special favour on the followers of the Prophet (Sallallaho alaihe wasallam)) raised the reward to twenty-seven times.\"", "rawOcrText": null, "ttsEligible": true, "verificationStatus": "in_review", "provenanceNotes": "Locked human-reviewed handoff: printed page 52"}]}'::jsonb);
FOR v_page IN SELECT page_data FROM temp_import_pages LOOP
  PERFORM import_new_structured_page_v1('3cbdc749-e9c9-44f3-8330-ecc1e3b38cc8'::uuid, '59d7f112-fb58-4726-9c35-11485c6155e7'::uuid, 'a2000000-0000-4000-8000-000000000001'::uuid, 'a3000000-0000-4000-8000-000000000001'::uuid, 'a4000000-0000-4000-8000-000000000005'::uuid, v_page);
END LOOP;
END;
$$;